<?php
namespace App\Services\Inventory;
use App\Models\{GlBatch,ItemLedger,Location,PostingSetup};
use App\Models\Inventory\{GoodsTransfer,GoodsTransferLine};
use App\Services\Audit\ActivityLogService;
use App\Services\Ledger\{GeneralLedgerService,ItemLedgerService};
use App\Services\Posting\PostingAccountResolver;
use App\Services\Pricing\ItemPriceService;
use App\Services\System\DocumentSequenceService;
use DomainException; use Illuminate\Support\Facades\DB;
class GoodsTransferPostingService {
 public function __construct(private ItemLedgerService $items,private GeneralLedgerService $gl,private PostingAccountResolver $accounts,private DocumentSequenceService $numbers,private LocationBinService $bins,private ActivityLogService $audit,private ItemPriceService $itemRules){}
 public function ship(GoodsTransfer $transfer,int $userId): void {DB::transaction(function()use($transfer,$userId){$transfer=GoodsTransfer::with(['lines.item','sourceLocation','destinationLocation','sourceBin','destinationBin'])->lockForUpdate()->findOrFail($transfer->id);if($transfer->status!=='RELEASED')throw new DomainException('Goods Transfer must be RELEASED before shipping.');$this->bins->validate($transfer->sourceLocation,$transfer->sourceBin);$this->bins->validate($transfer->destinationLocation,$transfer->destinationBin);$transit=Location::where('code','IN-TRANSIT')->where('is_system',true)->firstOrFail();$setup=PostingSetup::where('code','DEFAULT')->where('is_active',true)->firstOrFail();if(!$setup->inventory_in_transit_account_id)throw new DomainException('Inventory In Transit GL account is not configured.');$gl=[];foreach($transfer->lines as $line){$this->itemRules->assertEligible($line->item);$qty=(float)$line->quantity;if($qty<=0)throw new DomainException('Transfer quantity must be positive.');$available=$this->available($line->item_id,$transfer->source_location_id,$transfer->source_bin_id);if($available+0.0001<$qty)throw new DomainException("Insufficient stock for {$line->item->code}. Available {$available}, requested {$qty}.");$amount=round($qty*(float)$line->unit_cost,4);$inventory=$this->accounts->inventory($line->item);$gl[]=['account_id'=>$setup->inventory_in_transit_account_id,'debit'=>$amount,'credit'=>0,'description'=>"Transfer in transit {$line->item->code}"];$gl[]=['account_id'=>$inventory,'debit'=>0,'credit'=>$amount,'description'=>"Transfer source {$line->item->code}"];$this->items->post(['posting_at'=>now(),'source_module'=>'inventory.goods-transfer','document_type'=>'GOODS_TRANSFER_SHIP','document_number'=>$transfer->document_no,'item_id'=>$line->item_id,'warehouse_id'=>null,'location_id'=>$transfer->source_location_id,'bin_id'=>$transfer->source_bin_id,'qty_in'=>0,'qty_out'=>$qty,'unit_cost'=>$line->unit_cost,'amount'=>-$amount,'description'=>"Ship {$transfer->document_no}",'posted_by'=>$userId,'goods_transfer_id'=>$transfer->id,'movement_type'=>'TRANSFER_SHIP_SOURCE']);$this->items->post(['posting_at'=>now(),'source_module'=>'inventory.goods-transfer','document_type'=>'GOODS_TRANSFER_SHIP','document_number'=>$transfer->document_no,'item_id'=>$line->item_id,'warehouse_id'=>null,'location_id'=>$transit->id,'bin_id'=>null,'qty_in'=>$qty,'qty_out'=>0,'unit_cost'=>$line->unit_cost,'amount'=>$amount,'description'=>"In transit {$transfer->document_no}",'posted_by'=>$userId,'goods_transfer_id'=>$transfer->id,'movement_type'=>'TRANSFER_IN_TRANSIT_IN']);$line->update(['shipped_quantity'=>$qty]);}$this->gl->postBatch(['document_number'=>$transfer->document_no,'posting_at'=>now(),'source_module'=>'inventory.goods-transfer','document_type'=>'GOODS_TRANSFER_SHIP','description'=>"Goods Transfer Ship {$transfer->document_no}",'posted_by'=>$userId,'goods_transfer_id'=>$transfer->id],$gl);$transfer->update(['status'=>'SHIPPED','shipped_by'=>$userId,'shipped_at'=>now()]);$this->audit->record('inventory.transfers','ship',$transfer,[], $transfer->fresh()->toArray(),['document_number'=>$transfer->document_no]);});}
 public function receive(GoodsTransfer $transfer,array $quantities,int $userId,?string $notes=null): string {return DB::transaction(function()use($transfer,$quantities,$userId,$notes){$transfer=GoodsTransfer::with(['lines.item','destinationLocation','destinationBin'])->lockForUpdate()->findOrFail($transfer->id);if(!in_array($transfer->status,['SHIPPED'],true))throw new DomainException('Only SHIPPED transfer can be received.');$this->bins->validate($transfer->destinationLocation,$transfer->destinationBin);$transit=Location::where('code','IN-TRANSIT')->where('is_system',true)->firstOrFail();$setup=PostingSetup::where('code','DEFAULT')->where('is_active',true)->firstOrFail();if(!$setup->inventory_in_transit_account_id)throw new DomainException('Inventory In Transit GL account is not configured.');$receiptNo=$this->numbers->next('GOODS_TRANSFER_RECEIPT');$receipt=\App\Models\Inventory\GoodsTransferReceipt::create(['goods_transfer_id'=>$transfer->id,'receipt_no'=>$receiptNo,'received_at'=>now(),'received_by'=>$userId,'notes'=>$notes]);$gl=[];$receivedAny=false;foreach($transfer->lines as $line){$line=GoodsTransferLine::with('item')->lockForUpdate()->findOrFail($line->id);$this->itemRules->assertEligible($line->item);$qty=(float)($quantities[$line->id]??0);if($qty<=0)continue;$remaining=(float)$line->shipped_quantity-(float)$line->received_quantity;if($qty>$remaining+0.0001)throw new DomainException("Receive qty exceeds in-transit qty for {$line->item->code}.");$receivedAny=true;$amount=round($qty*(float)$line->unit_cost,4);$inventory=$this->accounts->inventory($line->item);$gl[]=['account_id'=>$inventory,'debit'=>$amount,'credit'=>0,'description'=>"Transfer destination {$line->item->code}"];$gl[]=['account_id'=>$setup->inventory_in_transit_account_id,'debit'=>0,'credit'=>$amount,'description'=>"Clear in transit {$line->item->code}"];$this->items->post(['posting_at'=>now(),'source_module'=>'inventory.goods-transfer','document_type'=>'GOODS_TRANSFER_RECEIVE','document_number'=>$receiptNo,'item_id'=>$line->item_id,'warehouse_id'=>null,'location_id'=>$transit->id,'bin_id'=>null,'qty_in'=>0,'qty_out'=>$qty,'unit_cost'=>$line->unit_cost,'amount'=>-$amount,'description'=>"Receive {$transfer->document_no}",'posted_by'=>$userId,'goods_transfer_id'=>$transfer->id,'movement_type'=>'TRANSFER_IN_TRANSIT_OUT']);$this->items->post(['posting_at'=>now(),'source_module'=>'inventory.goods-transfer','document_type'=>'GOODS_TRANSFER_RECEIVE','document_number'=>$receiptNo,'item_id'=>$line->item_id,'warehouse_id'=>null,'location_id'=>$transfer->destination_location_id,'bin_id'=>$transfer->destination_bin_id,'qty_in'=>$qty,'qty_out'=>0,'unit_cost'=>$line->unit_cost,'amount'=>$amount,'description'=>"Receive {$transfer->document_no}",'posted_by'=>$userId,'goods_transfer_id'=>$transfer->id,'movement_type'=>'TRANSFER_RECEIVE_DEST']);$receipt->lines()->create(['goods_transfer_line_id'=>$line->id,'quantity'=>$qty]);$line->increment('received_quantity',$qty);}if(!$receivedAny)throw new DomainException('Enter at least one receive quantity.');$this->gl->postBatch(['document_number'=>$receiptNo,'posting_at'=>now(),'source_module'=>'inventory.goods-transfer','document_type'=>'GOODS_TRANSFER_RECEIVE','description'=>"Goods Transfer Receive {$transfer->document_no}",'posted_by'=>$userId,'goods_transfer_id'=>$transfer->id],$gl);$complete=$transfer->lines()->get()->every(fn($l)=>(float)$l->received_quantity+0.0001>=(float)$l->shipped_quantity);if($complete)$transfer->update(['status'=>'RECEIVED','received_by'=>$userId,'received_at'=>now()]);$this->audit->record('inventory.transfers','receive',$transfer,[],['receipt_no'=>$receiptNo],['document_number'=>$transfer->document_no]);return $receiptNo;});}
 public function undo(GoodsTransfer $transfer,string $reason,int $userId): string {return DB::transaction(function()use($transfer,$reason,$userId){$transfer=GoodsTransfer::lockForUpdate()->findOrFail($transfer->id);if(!in_array($transfer->status,['SHIPPED','RECEIVED'],true))throw new DomainException('Only SHIPPED/RECEIVED transfer can be undone.');$undoNo=$this->numbers->next('UNDO');foreach(ItemLedger::where('goods_transfer_id',$transfer->id)->whereNull('reversal_of_id')->orderByDesc('id')->get() as $row)$this->items->post(['posting_at'=>now(),'source_module'=>'undo','document_type'=>'UNDO_TRANSFER','document_number'=>$undoNo,'item_id'=>$row->item_id,'warehouse_id'=>null,'location_id'=>$row->location_id,'bin_id'=>$row->bin_id,'qty_in'=>$row->qty_out,'qty_out'=>$row->qty_in,'unit_cost'=>$row->unit_cost,'amount'=>-(float)$row->amount,'description'=>"UNDO {$transfer->document_no}: {$reason}",'posted_by'=>$userId,'reversal_of_id'=>$row->id,'goods_transfer_id'=>$transfer->id,'movement_type'=>'TRANSFER_UNDO']);foreach(GlBatch::with('entries')->where('goods_transfer_id',$transfer->id)->whereNull('reversal_of_id')->orderByDesc('id')->get() as $batch){$lines=$batch->entries->map(fn($e)=>['account_id'=>$e->account_id,'debit'=>(float)$e->credit,'credit'=>(float)$e->debit,'description'=>"UNDO {$transfer->document_no}",'reversal_of_id'=>$e->id])->all();$this->gl->postBatch(['document_number'=>$undoNo.'-'.$batch->id,'posting_at'=>now(),'source_module'=>'undo','document_type'=>'UNDO_TRANSFER','description'=>"UNDO {$transfer->document_no}: {$reason}",'posted_by'=>$userId,'reversal_of_id'=>$batch->id,'goods_transfer_id'=>$transfer->id],$lines);}$transfer->update(['status'=>'UNDO','undone_by'=>$userId,'undone_at'=>now()]);$this->audit->record('inventory.transfers','undo',$transfer,[],['undo_no'=>$undoNo,'reason'=>$reason],['document_number'=>$transfer->document_no]);return$undoNo;});}
 private function available(int $itemId,int $locationId,?int $binId): float {$q=ItemLedger::where('item_id',$itemId)->where('location_id',$locationId);if($binId)$q->where('bin_id',$binId);else$q->whereNull('bin_id');return(float)$q->selectRaw('COALESCE(SUM(qty_in-qty_out),0) as bal')->value('bal');}
}
